Here is a clean implementation using Python's `requests` library:

```python
import requests

def fetch_data(url):
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()  # Raises HTTPError for 4xx/5xx codes
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f'Error fetching data: {e}')
        return None

# Example usage
data = fetch_data('https://api.github.com/users/octocat')
if data:
    print(f"User: {data.get('login')}")
```

